    "html": "<!DOCTYPE html>\r\n<html lang=\"en\">\r\n<head>\r\n<meta charset=\"UTF-8\">\r\n<link href=\"https://fonts.googleapis.com/css2?family=Space+Grotesk:wght@500;700&family=DM+Sans:wght@400;500;700&display=swap\" rel=\"stylesheet\">\r\n<script src=\"https://cdn.tailwindcss.com\"></script>\r\n<style>\r\n  body { width:1440px; height:900px; overflow:hidden; background:#FFF6E7; background-image: radial-gradient(rgba(40,36,30,0.07) 1.5px, transparent 1.5px); background-size: 18px 18px; }\r\n  .grotesk { font-family:'Space Grotesk',sans-serif; }\r\n  .dmsans { font-family:'DM Sans',sans-serif; }\r\n  .panel { background:#FFFDF6; border:3px solid #26221B; border-radius:16px; box-shadow: 7px 7px 0 #26221B; }\r\n  .btn3d { border:3px solid #26221B; border-radius:14px; box-shadow: 5px 5px 0 #26221B; transition: transform .1s ease, box-shadow .1s ease; }\r\n  .btn3d:active { transform: translate(4px,4px); box-shadow: 1px 1px 0 #26221B; }\r\n  .chip { border:2.5px solid #26221B; border-radius:9999px; box-shadow: 3px 3px 0 #26221B; }\r\n  .bubble { position:relative; }\r\n  .bubble:after { content:''; position:absolute; bottom:-16px; left:44px; width:0; height:0; border-left:14px solid transparent; border-right:14px solid transparent; border-top:16px solid #26221B; }\r\n  .bubble:before { content:''; position:absolute; bottom:-10px; left:46.5px; width:0; height:0; border-left:11px solid transparent; border-right:11px solid transparent; border-top:13px solid #FFD57E; z-index:1; }\r\n  .halftone { background-image: radial-gradient(rgba(38,34,27,0.16) 1.3px, transparent 1.3px); background-size: 9px 9px; }\r\n</style>\r\n</head>\r\n<body class=\"dmsans text-[#26221B]\">\r\n<div class=\"flex h-full\">\r\n\r\n  <!-- SIDEBAR -->\r\n  <aside class=\"w-[290px] shrink-0 flex flex-col px-5 pt-6 pb-5 border-r-3\" style=\"border-right:3px solid #26221B\">\r\n    <div class=\"panel halftone px-5 py-5 mb-5\">\r\n      <div class=\"grotesk text-[24px] font-bold leading-tight\">Classroom Tools</div>\r\n      <div class=\"mt-1 text-[11px] font-bold uppercase tracking-[0.25em] text-[#C43D2E]\">Level Up Rewards</div>\r\n    </div>\r\n\r\n    <div class=\"flex-1 space-y-6 overflow-hidden px-1\">\r\n      <button class=\"btn3d w-full py-4 bg-[#3D4E8D] text-white grotesk font-bold text-sm tracking-wide\">Arrange Seats</button>\r\n\r\n      <div>\r\n        <div class=\"flex items-center justify-between mb-3 px-1\">\r\n          <span class=\"grotesk font-bold text-[11px] uppercase tracking-[0.18em]\">Add Points</span>\r\n          <span class=\"text-[9px] font-bold uppercase tracking-widest bg-[#3BA57F] text-white px-2 py-1 rounded-full chip\">+5 to class</span>\r\n        </div>\r\n        <div class=\"grid grid-cols-3 gap-3\">\r\n          <button class=\"btn3d py-3 bg-[#FFD57E] grotesk font-bold\">+1</button>\r\n          <button class=\"btn3d py-3 bg-[#FFAB95] grotesk font-bold\">+5</button>\r\n          <button class=\"btn3d py-3 bg-[#C9AEFF] grotesk font-bold\">+10</button>\r\n        </div>\r\n      </div>\r\n\r\n      <div class=\"space-y-4\">\r\n        <button class=\"btn3d w-full py-3.5 bg-[#FFDE76] grotesk font-bold text-sm text-left px-5\">🎲 Random Student</button>\r\n        <button class=\"btn3d w-full py-3.5 bg-[#C9AEFF] grotesk font-bold text-sm text-left px-5\">🎟 Raffle Draw</button>\r\n        <button class=\"btn3d w-full py-3.5 bg-[#FFAB95] grotesk font-bold text-sm text-left px-5\">📋 Behavior Log</button>\r\n        <button class=\"btn3d w-full py-3.5 bg-[#8FDCC0] grotesk font-bold text-sm text-left px-5\">✅ Attendance Roll</button>\r\n      </div>\r\n\r\n      <div>\r\n        <div class=\"grotesk font-bold text-[11px] uppercase tracking-[0.18em] mb-3 px-1\">Class Timer</div>\r\n        <div class=\"panel p-4 text-center\">\r\n          <div class=\"grotesk text-[38px] font-bold leading-none\">15:00</div>\r\n          <div class=\"flex gap-2 mt-3\">\r\n            <button class=\"btn3d flex-1 py-2.5 bg-[#8FDCC0] text-xs grotesk font-bold uppercase\">Start</button>\r\n            <button class=\"btn3d flex-1 py-2.5 bg-[#FFFDF6] text-xs grotesk font-bold uppercase\">Reset</button>\r\n          </div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n\r\n    <button class=\"btn3d w-full py-3.5 mt-5 bg-[#FFFDF6] grotesk font-bold text-xs uppercase tracking-widest\">Room Settings</button>\r\n  </aside>\r\n\r\n  <!-- CANVAS -->\r\n  <main class=\"flex-1 flex flex-col\">\r\n    <header class=\"mx-8 mt-6 shrink-0 flex items-center justify-between px-2 pb-4\" style=\"border-bottom:3px solid #26221B\">\r\n      <div class=\"flex items-center gap-5\">\r\n        <button class=\"btn3d px-4 py-2 bg-[#FFD57E] grotesk font-bold text-xs\">Grade 5 ▾</button>\r\n        <span class=\"text-[11px] font-bold uppercase tracking-[0.2em] flex items-center gap-2\"><span class=\"w-2.5 h-2.5 rounded-full\" style=\"background:#26221B\"></span>12/22 present</span>\r\n      </div>\r\n      <div class=\"flex items-center gap-3\">\r\n        <button class=\"btn3d px-4 py-2 bg-[#3D4E8D] text-white text-[11px] grotesk font-bold\">Projector</button>\r\n        <button class=\"btn3d px-4 py-2 bg-[#3D4E8D] text-white text-[11px] grotesk font-bold\">Shortcuts</button>\r\n        <div class=\"w-9 h-9 rounded-full bg-[#F97F62] flex items-center justify-center text-[10px] grotesk font-bold text-white chip\">TR</div>\r\n      </div>\r\n    </header>\r\n\r\n    <div class=\"flex-1 relative overflow-auto px-10 pt-9 pb-10\">\r\n      <div class=\"flex justify-center mb-10\">\r\n        <div class=\"panel bg-[#FFD57E] px-12 py-4 text-center bubble\">\r\n          <div class=\"text-[9px] grotesk font-bold uppercase tracking-[0.35em]\">Front of class</div>\r\n          <div class=\"grotesk text-lg font-bold uppercase tracking-[0.18em]\">Teacher Desk</div>\r\n        </div>\r\n      </div>\r\n      <div id=\"grid\" class=\"grid grid-cols-5 gap-x-7 gap-y-9 max-w-[1060px] mx-auto\"></div>\r\n    </div>\r\n  </main>\r\n</div>\r\n\r\n<script>\r\nconst students = [\r\n  [\"JD\",\"John Davis\",\"87 PTS\",\"+5 PTS\",\"#FFD57E\",\"#8A5410\"],\r\n  [\"EW\",\"Emily Ward\",\"1.2K PTS\",\"+10 PTS\",\"#F97F62\",\"#8A2A1E\"],\r\n  [\"ZJ\",\"Zoe Jenkins\",\"462 PTS\",\"STAR!\",\"#8FDCC0\",\"#1E6B4C\"],\r\n  [\"LH\",\"Leo Hayes\",\"890 PTS\",\"+5 PTS\",\"#C9AEFF\",\"#5B3A9E\"],\r\n  [\"AB\",\"Ava Brooks\",\"2.1K PTS\",\"GOAL!\",\"#7FB8E8\",\"#25598A\"],\r\n  [\"KM\",\"Kai Miller\",\"66 PTS\",\"+15 PTS\",\"#FFD57E\",\"#8A5410\"],\r\n  [\"SO\",\"Sarah O'Neill\",\"94 PTS\",\"+5 PTS\",\"#F97F62\",\"#8A2A1E\"],\r\n  [\"RR\",\"Ryan Reed\",\"118 PTS\",\"+10 PTS\",\"#8FDCC0\",\"#1E6B4C\"],\r\n  [\"MP\",\"Mia Park\",\"2.4K PTS\",\"SUPER!\",\"#C9AEFF\",\"#5B3A9E\"],\r\n  [\"TL\",\"Toby Long\",\"1.9K PTS\",\"+20 PTS\",\"#7FB8E8\",\"#25598A\"]\r\n];\r\nconst grid = document.getElementById('grid');\r\nstudents.forEach(([init,name,pts,bang,c,cText]) => {\r\n  grid.insertAdjacentHTML('beforeend', `\r\n  <div class=\"panel relative px-3 py-6 text-center cursor-pointer hover:-translate-y-1 transition-transform\">\r\n    <div class=\"absolute -top-3.5 -right-2.5 px-2.5 py-1 grotesk text-[10px] font-bold text-white rotate-[8deg] chip\" style=\"background:#C43D2E\">${bang}</div>\r\n    <div class=\"w-16 h-16 mx-auto rounded-xl flex items-center justify-center grotesk text-xl font-bold chip halftone\" style=\"background:${c};color:${cText}\">${init}</div>\r\n    <div class=\"mt-3 grotesk font-bold text-[15px] leading-tight\">${name}</div>\r\n    <div class=\"mt-2.5 inline-block text-[10px] grotesk font-bold uppercase tracking-widest px-3 py-1 chip bg-[#FFFDF6]\">${pts}</div>\r\n  </div>`);\r\n});\r\nfor (let i=0;i<3;i++) {\r\n  grid.insertAdjacentHTML('beforeend', `\r\n  <div class=\"relative px-3 py-6 text-center border-3 border-dashed border-[#B7AD98] bg-white/40\" style=\"border:3px dashed #B7AD98; border-radius:16px\">\r\n    <div class=\"w-16 h-16 mx-auto rounded-xl\" style=\"border:3px dashed #B7AD98\"></div>\r\n    <div class=\"mt-3 grotesk font-bold text-[11px] uppercase tracking-[0.25em] text-[#9A9080]\">Empty desk</div>\r\n  </div>`);\r\n}\r\n</script>\r\n</body>\r\n</html>\r\n"
